/**
 * ============================================================================
 * About globe — data
 * ============================================================================
 * Two kinds of data live here:
 *
 *  1. `GLOBE_DESTINATIONS` / `GLOBE_ROUTES` — hand-curated: the nine places the
 *     globe pins, and the five great-circle routes drawn between them. Ids are
 *     local to the globe; the visible names match the destination ticker below
 *     the section.
 *
 *  2. `LAND_DOT_DATA` — generated, do not edit by hand. ~4.5k evenly spaced
 *     points (a Fibonacci sphere) filtered down to land by
 *     `scripts/generate-globe-dots.mjs`, which tests them against Natural Earth
 *     1:50m land polygons (the `world-atlas` package) with `d3-geo`. The dot
 *     field is what makes the continents readable on the otherwise abstract
 *     sphere.
 *
 * Regenerate the field with `npm run generate:globe-dots` after changing the
 * density, the coastline source or the pole trim in that script.
 */

export type GlobeDestination = {
  /** Stable id used by `GLOBE_ROUTES` and the HTML label layer. */
  id: string
  /** Label shown beside the pin — the same name the ticker uses. */
  name: string
  lat: number
  lng: number
}

/** Pins on the globe, in ticker order: west → east around the world. */
export const GLOBE_DESTINATIONS: readonly GlobeDestination[] = [
  { id: 'iceland', name: 'Iceland', lat: 64.1, lng: -21.9 },
  { id: 'morocco', name: 'Morocco', lat: 31.6, lng: -7.9 },
  { id: 'switzerland', name: 'Switzerland', lat: 46.6, lng: 7.9 },
  { id: 'tanzania', name: 'Tanzania', lat: -3.4, lng: 35.7 },
  { id: 'nepal', name: 'Nepal', lat: 28, lng: 84 },
  { id: 'japan', name: 'Japan', lat: 35, lng: 135.8 },
  { id: 'new-zealand', name: 'New Zealand', lat: -44, lng: 170.5 },
  { id: 'patagonia', name: 'Patagonia', lat: -49.3, lng: -72.9 },
  { id: 'peru', name: 'Peru', lat: -13.5, lng: -71.9 },
]

/**
 * Routes drawn as faint great-circle arcs. Kept short and regional so the globe
 * reads as a route network rather than a ball of yarn: Himalaya–Japan,
 * Alps–Iceland, Morocco–Tanzania, New Zealand–Japan, Peru–Patagonia.
 */
export const GLOBE_ROUTES: readonly (readonly [string, string])[] = [
  ['nepal', 'japan'],
  ['switzerland', 'iceland'],
  ['morocco', 'tanzania'],
  ['japan', 'new-zealand'],
  ['peru', 'patagonia'],
]

